insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-desert-10195-hold-main-s648','decision','College of the Desert 10195 keeps main''s record; a read of the wrong section is never filed','The S648 conductor, #3240: paid read 43421133593 extracted 10195 (Natural Resources A.S.) from 07908''s employment-preparation section. A guarded UPDATE restored main''s record (receipt program_requirement_records_restore_desert_10195_s648_2026-11-13.sql, md5-checked). COBIx: that run''s artifact is never reposted for 10195. No stored hold exists yet: a future paid read extracts it again.',array['program-requirements-harvest','decision'],'proposed','S648, PR 3240; restore receipt',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-course-key-normalized-s648','decision','A course is one college and code key; SLOs match on that key','The S648 conductor, #3242 (e8985e00): a course is distinct by (college, code uppercased with spaces and hyphens removed), and an SLO matches on that key; the checkpoint''s harvest row and the Commons data dashboard both use it. Live read 17:33Z 2026-11-13: raw pairs 89,192 and 12,815 with SLOs; the key 88,736 and 13,293; blank codes 0.',array['commons','program-requirements-harvest','decision'],'proposed','S648, PR 3242',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-official-name-source-confidence-s648','decision','No person signs off before a new official name is proposed; the name source is recorded','The S648 conductor on COBIx''s recommendation, #3241 (bbfbb6bb): no person confirms a new official name before a batch proposes it. A Review record carries name_source: strong (the catalog holds the issuer''s own page), partial (a sibling exhibit carries it) or limited, shown as a word beside the proposal and never holding it back. Answers Sheet 192 card 6 question 1.',array['cer-procedures','exhibits','decision'],'proposed','S648, PR 3241; issue 3223',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-comptia-after-ase-s648','decision','CompTIA''s batch follows ASE''s, ahead of AWS and NCCER','The S648 conductor on COBIx''s recommendation, #3241: CompTIA''s rename batch follows the ASE batch and comes ahead of the American Welding Society and NCCER. Answers Sheet 192 card 6 question 4.',array['cer-procedures','exhibits','decision'],'proposed','S648, PR 3241; issue 3223',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-named-credential-issuer-tag-or-half-s648','decision','An issuer is named by an explicit tag list; a title several issuers share names none','The S648 conductor, #3241 and #3248: a course names an issuer only when its title carries one of the issuer''s tags (kb/reference/issuer_tags.json) or enough of its name; never by pattern. A bare title several issuers carry names none without its tag, so NFPA''s and Pro Board''s bare Fire Inspector and Fire Officer titles and EMS 20 (NREMT and EMSA) go to a person.',array['cer-procedures','exhibits','decision'],'proposed','S648, PRs 3241 and 3248',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-or-between-tests-coded-as-written-s648','decision','An "or" between two tests in an ASE bundle is coded as written','The S648 conductor on COBIx''s reading of Sam''s "defer to it''s mix as written", #3241: ASE Bundle - A6 or T6 + L3 is its own mix, ASE Certificate Bundles: A6 or T6 + L3, renamed only through the next rename batch Sam approves. A choice alone (C1 or G1) stays any one test; an "or" inside a comma list (A4, A5 or A6) goes to a person. Answers Sheet 192 card 5.',array['cer-procedures','exhibits','decision'],'proposed','S648, PR 3241; issue 3228',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-comptia-series-is-alias-s648','decision','A CompTIA title never carries its exam series; the series is a search alias','The S648 conductor on COBIx''s recommendation, #3241: a CompTIA title is the certification''s name without its exam series (CompTIA Cloud+, not CV0-004); the series is kept as a search alias (cert_naming.series_aside); a course title is never stripped. COBIx is also raising the exam-series question with Sam. Answers Sheet 192 card 6 question 2.',array['cer-procedures','exhibits','decision'],'proposed','S648, PR 3241; issue 3223',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-calgetc-34-per-college-evidence-s648','decision','The statewide Cal-GETC 34 runs only where a college''s config quotes evidence','The S648 conductor, #3244 (74ad28b9), carrying Sam''s Sheet 187 card 5: the statewide 34 runs for a college only when its reconcile config quotes evidence that its catalog names Cal-GETC and prints no figure; a college printing its own takes a set step. A combined General Education (Cal-GETC) and Elective Courses N line is a printed figure. Record gates hold on top.',array['program-requirements-harvest','decision'],'proposed','S648, PR 3244; kb/program_requirements_calgetc_34_plan.json',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-calgetc-short-fills-by-sheet-81-s648','decision','A 60-unit transfer degree under 60 after Cal-GETC fills by Sheet 81 card 2','The S648 conductor, #3244: a transfer degree at 60 units whose major plus Cal-GETC sums under 60 fills the difference under Sam''s Sheet 81 card 2 ruling, rather than failing the total. Twelve programs fill under the plan: Cosumnes River 3, Cerro Coso 6, Grossmont 1, and existing steps at College of Alameda and East Los Angeles.',array['program-requirements-harvest','decision'],'proposed','S648, PR 3244',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-glendale-tab-control-number-s648','decision','A Coursedog tab''s own control number decides its owner','The S648 conductor, #3202 (draft): Glendale''s reader keeps each Coursedog tab''s control number, so the tab''s own number decides which program owns it (NCHSD''s tab names 31597). A tab stays shared only for 2.0 successors whose title adds numbers alone. A hold restores main''s copy and never deletes or replaces a passing record; the load skips 12571 and 37070.',array['program-requirements-harvest','decision'],'proposed','S648, PR 3202',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-reclustering-three-held-s648','decision','Re-clustering: AJ 160, MUS 130 and REAL held; MATH M1044 held; the BUSI split insert-only','The S648 conductor, #3245 (draft, nothing applied): AJ 160 and MUS 130 are held (an official placement by ASCCC approval or COCI C-ID entry is not set aside by an outcome score); REAL M1038 with M1040 held (both are required for the salesperson license); MATH M1044 into M1036 held for a likely mis-filed refrigeration lab articulation. The BUSI M1228 split is insert-only.',array['commons','re-clustering','decision'],'proposed','S648, PR 3245; kb/status/mid_outcomes_compare_2026-11-12.md',null,null,'SkyTanager (S648)',date '2026-11-13'),
('d-data-collection-two-bases-s648','decision','College Data Collection cards state their base; captures count Active, Teachout and Approved','The S648 conductor, #3243 (ac7c6595): each College Data Collection card names its base. The captures figure counts Active, Teachout and Approved programs (22,335 = 20,282 + 630 + 1,423); the passing and completeness figures count Active programs.',array['commons','decision'],'proposed','S648, PR 3243; issue 3229',null,null,'SkyTanager (S648)',date '2026-11-13')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyTanager (S648)', 'create', 'checkpoint auto-write (S648, 2026-11-13)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-desert-10195-hold-main-s648','d-course-key-normalized-s648','d-official-name-source-confidence-s648','d-comptia-after-ase-s648','d-named-credential-issuer-tag-or-half-s648','d-or-between-tests-coded-as-written-s648','d-comptia-series-is-alias-s648','d-calgetc-34-per-college-evidence-s648','d-calgetc-short-fills-by-sheet-81-s648','d-glendale-tab-control-number-s648','d-reclustering-three-held-s648','d-data-collection-two-bases-s648')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-desert-10195-hold-main-s648','d-course-key-normalized-s648','d-official-name-source-confidence-s648','d-comptia-after-ase-s648','d-named-credential-issuer-tag-or-half-s648','d-or-between-tests-coded-as-written-s648','d-comptia-series-is-alias-s648','d-calgetc-34-per-college-evidence-s648','d-calgetc-short-fills-by-sheet-81-s648','d-glendale-tab-control-number-s648','d-reclustering-three-held-s648','d-data-collection-two-bases-s648')
group by m.slug, m.summary order by m.slug;
